const describedControls = new WeakMap();
/** Connects a control to description elements in its tree or an ancestor tree. */
const setAccessibleDescriptionElements = (control, elements) => {
    if (!control || !('ariaDescribedByElements' in control))
        return;
    const description = control.getAttribute('aria-describedby');
    if (elements !== undefined) {
        if (!describedControls.has(control) || description !== '')
            describedControls.set(control, description);
        control.ariaDescribedByElements = elements;
    }
    else {
        const previousDescription = describedControls.get(control);
        describedControls.delete(control);
        if (previousDescription !== undefined && description === '') {
            control.ariaDescribedByElements = null;
            if (previousDescription !== null)
                control.setAttribute('aria-describedby', previousDescription);
        }
    }
};

